import { test, expect } from '@playwright/test';

test.describe('Notification Message Rendering', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/notification_message_rendered');
  });

  test('should display notification after clicking the action link', async ({ page }) => {
    // Verify initial state
    const flashElement = page.locator('#flash');
    await expect(flashElement).not.toBeVisible();

    // Click the action link
    const clickLink = page.getByRole('link', { name: 'Click here' });
    await clickLink.click();

    // Verify notification appears
    await expect(flashElement).toBeVisible();

    // Verify notification text contains success message
    const notificationText = await flashElement.textContent();
    expect(notificationText).toContain('Action successful');

    // Verify notification has a close button
    const closeButton = page.locator('[data-testid="close-button"]');
    await expect(closeButton).toBeVisible();

    // Dismiss the notification
    await closeButton.click();

    // Verify notification is dismissed
    await expect(flashElement).not.toBeVisible();
  });

  test('should handle notification with unsuccessful action and dismiss it', async ({ page }) => {
    // Click the action link
    const clickLink = page.getByRole('link', { name: 'Click here' });
    await clickLink.click();

    // Verify notification appears
    const flashElement = page.locator('#flash');
    await expect(flashElement).toBeVisible();

    // Verify notification text contains unsuccessful message
    const notificationText = await flashElement.textContent();
    expect(notificationText).toContain('Action unsuccessful');

    // Verify notification has a close button
    const closeButton = page.locator('[data-testid="close-button"]');
    await expect(closeButton).toBeVisible();

    // Dismiss the notification
    await closeButton.click();

    // Verify notification is dismissed
    await expect(flashElement).not.toBeVisible();
  });
});
